// Checkout expects this interface everywhere:
interface PaymentGateway {
  charge(amountDollars: number): Promise<void>;
}

// But the legacy SDK looks nothing like it:
class LegacyGateway {
  submitPayment(cents: number, currencyCode: string): Promise<void> { /* ... */ }
}

// Checkout code would have to special-case the legacy shape everywhere

code.after:
class LegacyGatewayAdapter implements PaymentGateway {
  constructor(private legacy: LegacyGateway) {}

  async charge(amountDollars: number): Promise<void> {
    const cents = Math.round(amountDollars * 100);
    await this.legacy.submitPayment(cents, "USD");
  }
}

// Checkout code never changes:
const gateway: PaymentGateway = new LegacyGatewayAdapter(new LegacyGateway());
await gateway.charge(49.99);
